<?php
declare(strict_types=1);require_once __DIR__.'/includes/init.php';require_role('encargado','docente');
$pageTitle='Búsqueda';$term=trim((string)($_GET['q']??''));$results=['salas'=>[],'equipos'=>[],'profesores'=>[],'tickets'=>[]];$p=db();
if($term!==''){
 $like='%'.$term.'%';
 if(is_encargado()){
  $s=$p->prepare("SELECT id,nombre,ubicacion FROM salas WHERE eliminado_en IS NULL AND (nombre LIKE :q OR ubicacion LIKE :q2) ORDER BY nombre LIMIT 20");$s->execute(['q'=>$like,'q2'=>$like]);$results['salas']=$s->fetchAll();
  $s=$p->prepare("SELECT e.id,e.codigo_inventario,e.tipo,e.estado,s.id sala_id,s.nombre sala FROM equipos e JOIN salas s ON s.id=e.sala_id WHERE e.eliminado_en IS NULL AND (e.codigo_inventario LIKE :q OR e.marca LIKE :q2 OR e.sistema_operativo LIKE :q3 OR s.nombre LIKE :q4) ORDER BY e.codigo_inventario LIMIT 30");$s->execute(['q'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like]);$results['equipos']=$s->fetchAll();
  $s=$p->prepare("SELECT DISTINCT u.id,u.nombre,u.apellido,u.email FROM usuarios u JOIN usuario_turnos ut ON ut.usuario_id=u.id WHERE u.rol='docente' AND u.eliminado_en IS NULL AND ut.turno_id=:t AND ut.eliminado_en IS NULL AND (u.nombre LIKE :q OR u.apellido LIKE :q2 OR u.email LIKE :q3 OR u.cedula LIKE :q4) ORDER BY u.apellido,u.nombre LIMIT 20");$s->execute(['t'=>manager_turn_id(),'q'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like]);$results['profesores']=$s->fetchAll();
  $s=$p->prepare("SELECT t.id,t.tipo_problema,t.estado,t.urgencia,s.nombre sala,COALESCE(e.codigo_inventario,'Sin equipo') equipo FROM tickets t JOIN salas s ON s.id=t.sala_id LEFT JOIN equipos e ON e.id=t.equipo_id WHERE t.turno_id=:turno AND (CAST(t.id AS CHAR) LIKE :q OR t.descripcion LIKE :q2 OR s.nombre LIKE :q3 OR e.codigo_inventario LIKE :q4) ORDER BY t.creado_en DESC LIMIT 30");$s->execute(['turno'=>manager_turn_id(),'q'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like]);$results['tickets']=$s->fetchAll();
 }else{
  $uid=(int)current_user()['id'];
  $s=$p->prepare("SELECT DISTINCT s.id,s.nombre,s.ubicacion FROM salas s JOIN asignaciones_salas a ON a.sala_id=s.id WHERE a.docente_id=:d AND a.anio_lectivo=YEAR(CURDATE()) AND a.activa=1 AND s.eliminado_en IS NULL AND (s.nombre LIKE :q OR s.ubicacion LIKE :q2) ORDER BY s.nombre LIMIT 20");$s->execute(['d'=>$uid,'q'=>$like,'q2'=>$like]);$results['salas']=$s->fetchAll();
  $s=$p->prepare("SELECT DISTINCT e.id,e.codigo_inventario,e.tipo,e.estado,s.id sala_id,s.nombre sala FROM equipos e JOIN salas s ON s.id=e.sala_id JOIN asignaciones_salas a ON a.sala_id=s.id WHERE a.docente_id=:d AND a.anio_lectivo=YEAR(CURDATE()) AND a.activa=1 AND e.eliminado_en IS NULL AND (e.codigo_inventario LIKE :q OR e.marca LIKE :q2 OR e.sistema_operativo LIKE :q3 OR s.nombre LIKE :q4) ORDER BY e.codigo_inventario LIMIT 30");$s->execute(['d'=>$uid,'q'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like]);$results['equipos']=$s->fetchAll();
  $s=$p->prepare("SELECT t.id,t.tipo_problema,t.estado,t.urgencia,s.nombre sala,COALESCE(e.codigo_inventario,'Sin equipo') equipo FROM tickets t JOIN salas s ON s.id=t.sala_id LEFT JOIN equipos e ON e.id=t.equipo_id WHERE t.docente_id=:d AND (CAST(t.id AS CHAR) LIKE :q OR t.descripcion LIKE :q2 OR s.nombre LIKE :q3 OR e.codigo_inventario LIKE :q4) ORDER BY t.creado_en DESC LIMIT 30");$s->execute(['d'=>$uid,'q'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like]);$results['tickets']=$s->fetchAll();
 }
}
require __DIR__.'/includes/header.php';
?>
<section class="card search-page"><div class="card-body"><form method="get" class="global-search global-search--page"><label for="search-main">Buscar en el sistema</label><div><input id="search-main" name="q" value="<?=e($term)?>" placeholder="PC-12, Sala 3, apellido, ticket..." autofocus><button class="btn btn-primary">Buscar</button></div></form></div></section>
<?php if($term===''):?><div class="empty-state mt-3">Escribí un código de equipo, sala, profesor o número de ticket.</div><?php else:?>
<div class="search-results mt-3">
 <section class="card"><div class="card-header"><h2>Salas</h2><span class="card-header-note"><?=count($results['salas'])?> resultados</span></div><div class="card-body"><?php if(!$results['salas']):?><p class="text-muted">Sin coincidencias.</p><?php else:?><ul class="result-list"><?php foreach($results['salas'] as $r):?><li><a href="<?=e(url('sala.php?id='.(int)$r['id']))?>"><strong><?=e($r['nombre'])?></strong><span><?=e($r['ubicacion']??'Sin ubicación')?></span></a></li><?php endforeach;?></ul><?php endif;?></div></section>
 <section class="card"><div class="card-header"><h2>Equipos</h2><span class="card-header-note"><?=count($results['equipos'])?> resultados</span></div><div class="card-body"><?php if(!$results['equipos']):?><p class="text-muted">Sin coincidencias.</p><?php else:?><ul class="result-list"><?php foreach($results['equipos'] as $r):?><li><a href="<?=e(url('sala.php?id='.(int)$r['sala_id']))?>"><strong><?=e($r['codigo_inventario'])?></strong><span><?=e($r['sala'].' · '.equipment_type_label($r['tipo']))?> · <?=e(ucwords(str_replace('_',' ',$r['estado'])))?></span></a></li><?php endforeach;?></ul><?php endif;?></div></section>
 <?php if(is_encargado()):?><section class="card"><div class="card-header"><h2>Profesores</h2><span class="card-header-note"><?=count($results['profesores'])?> resultados</span></div><div class="card-body"><?php if(!$results['profesores']):?><p class="text-muted">Sin coincidencias.</p><?php else:?><ul class="result-list"><?php foreach($results['profesores'] as $r):?><li><a href="<?=e(url('encargado/usuario_editar.php?id='.(int)$r['id']))?>"><strong><?=e($r['apellido'].', '.$r['nombre'])?></strong><span><?=e($r['email'])?></span></a></li><?php endforeach;?></ul><?php endif;?></div></section><?php endif;?>
 <section class="card"><div class="card-header"><h2>Tickets</h2><span class="card-header-note"><?=count($results['tickets'])?> resultados</span></div><div class="card-body"><?php if(!$results['tickets']):?><p class="text-muted">Sin coincidencias.</p><?php else:?><ul class="result-list"><?php foreach($results['tickets'] as $r):?><li><a href="<?=e(url('ticket.php?id='.(int)$r['id']))?>"><strong>#<?=(int)$r['id']?> · <?=e(ucwords(str_replace('_',' ',$r['tipo_problema'])))?></strong><span><?=e($r['sala'].' · '.$r['equipo'])?></span></a></li><?php endforeach;?></ul><?php endif;?></div></section>
</div>
<?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>
